css:
.bd { display: flex; gap: 8px; }
.bd span { width: 14px; height: 14px; border-radius: 50%; background: #6366f1; animation: bd-bounce 0.9s ease-in-out infinite; }
.bd span:nth-child(2) { animation-delay: 0.15s; }
.bd span:nth-child(3) { animation-delay: 0.3s; }
@keyframes bd-bounce { 0%, 80%, 100% { transform: translateY(0); opacity: 0.5; } 40% { transform: translateY(-14px); opacity: 1; } }

.ib { position: relative; width: 240px; height: 6px; overflow: hidden; border-radius: 999px; background: #e5e7eb; }
.ib-fill { position: absolute; top: 0; left: 0; width: 40%; height: 100%; border-radius: 999px; background: #10b981; animation: ib-slide 1.2s ease-in-out infinite; }
@keyframes ib-slide { 0% { transform: translateX(-100%); } 100% { transform: translateX(250%); } }

.rp { position: relative; width: 64px; height: 64px; }
.rp span { position: absolute; inset: 0; border: 4px solid #0ea5e9; border-radius: 50%; opacity: 0; animation: rp-ripple 1.6s ease-out infinite; }
.rp span:nth-child(2) { animation-delay: 0.8s; }
@keyframes rp-ripple { 0% { transform: scale(0.2); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }

.wv { display: flex; align-items: center; gap: 5px; height: 44px; }
.wv span { width: 6px; height: 100%; border-radius: 3px; background: #8b5cf6; animation: wv-wave 1s ease-in-out infinite; }
.wv span:nth-child(2) { animation-delay: 0.1s; }
.wv span:nth-child(3) { animation-delay: 0.2s; }
.wv span:nth-child(4) { animation-delay: 0.3s; }
.wv span:nth-child(5) { animation-delay: 0.4s; }
@keyframes wv-wave { 0%, 40%, 100% { transform: scaleY(0.3); } 20% { transform: scaleY(1); } }

.bt { margin: 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; font-size: 20px; font-weight: 700; letter-spacing: 2px; color: #374151; }
.bt span { animation: bt-blink 1.2s infinite; }
.bt span:nth-child(2) { animation-delay: 0.2s; }
.bt span:nth-child(3) { animation-delay: 0.4s; }
@keyframes bt-blink { 0%, 20% { opacity: 0; } 50% { opacity: 1; } 100% { opacity: 0; } }

.cpg { animation: cpg-rotate 1.6s linear infinite; }
.cpg circle { fill: none; stroke-width: 5; }
.cpg-track { stroke: #e5e7eb; }
.cpg-arc { stroke: #14b8a6; stroke-linecap: round; stroke-dasharray: 20 106; animation: cpg-dash 1.4s ease-in-out infinite; }
@keyframes cpg-rotate { to { transform: rotate(360deg); } }
@keyframes cpg-dash { 0% { stroke-dasharray: 4 122; stroke-dashoffset: 0; } 50% { stroke-dasharray: 80 46; stroke-dashoffset: -20; } 100% { stroke-dasharray: 4 122; stroke-dashoffset: -124; } }
